// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

contract SearchIndexPool is AccessControl, ReentrancyGuard {
    using ECDSA for bytes32;

    bytes32 public constant INDEXER_ROLE = keccak256("INDEXER_ROLE");
    bytes32 public constant POOL_MANAGER_ROLE = keccak256("POOL_MANAGER_ROLE");

    struct Connection {
        address owner;
        uint256 poolId;
        uint64 createdAt;
        uint64 lastUsed;
        bool active;
        uint8 priority;
    }

    struct Pool {
        uint256 maxConnections;
        uint256 activeConnections;
        address manager;
        mapping(uint256 => Connection) connections;
        uint256 nextConnId;
    }

    mapping(uint256 => Pool) public pools;
    uint256 public nextPoolId;

    mapping(address => mapping(uint256 => uint256[])) private userConnections;
    mapping(bytes32 => uint256) private delegationNonces;

    event ConnectionCreated(uint256 poolId, uint256 connId, address owner);
    event PoolCreated(uint256 poolId, address manager);
    event RoleDelegated(address from, address to, bytes32 role);

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(POOL_MANAGER_ROLE, msg.sender);
    }

    function createPool(uint256 maxConns) external onlyRole(POOL_MANAGER_ROLE) returns (uint256) {
        uint256 poolId = nextPoolId++;
        Pool storage pool = pools[poolId];
        pool.maxConnections = maxConns;
        pool.manager = msg.sender;
        emit PoolCreated(poolId, msg.sender);
        return poolId;
    }

    function acquireConnection(uint256 poolId, uint8 priority) external nonReentrant returns (uint256) {
        require(hasRole(INDEXER_ROLE, msg.sender) || hasRole(POOL_MANAGER_ROLE, msg.sender), "Unauthorized");
        Pool storage pool = pools[poolId];
        require(pool.activeConnections < pool.maxConnections, "Pool full");

        uint256 connId = pool.nextConnId++;
        pool.connections[connId] = Connection({
            owner: msg.sender,
            poolId: poolId,
            createdAt: uint64(block.timestamp),
            lastUsed: uint64(block.timestamp),
            active: true,
            priority: priority
        });
        pool.activeConnections++;
        userConnections[msg.sender][poolId].push(connId);

        emit ConnectionCreated(poolId, connId, msg.sender);
        return connId;
    }

    function releaseConnection(uint256 poolId, uint256 connId) external nonReentrant {
        Pool storage pool = pools[poolId];
        Connection storage conn = pool.connections[connId];
        require(conn.owner == msg.sender || hasRole(POOL_MANAGER_ROLE, msg.sender), "Not owner");
        require(conn.active, "Already released");

        conn.active = false;
        pool.activeConnections--;
    }

    /// @notice Delegate indexer capabilities to another address with nonce-based replay protection
    /// @dev Uses structured delegation with domain separation
    function delegateIndexerRole(
        address delegatee,
        uint256 poolId,
        bytes32 salt,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external nonReentrant {
        require(hasRole(INDEXER_ROLE, msg.sender), "Caller must be indexer");
        require(delegatee != address(0), "Invalid delegatee");

        bytes32 delegationKey = keccak256(abi.encodePacked(msg.sender, delegatee, poolId));
        uint256 nonce = delegationNonces[delegationKey]++;

        bytes32 messageHash = keccak256(abi.encodePacked(msg.sender, delegatee, poolId, nonce, salt));
        bytes32 ethSignedHash = ECDSA.toEthSignedMessageHash(messageHash);

        // ECDSA.recover enforces signature malleability protection (low-s, valid v)
        // and reverts on invalid signatures instead of returning address(0)
        address recovered = ECDSA.recover(ethSignedHash, v, r, s);
        require(recovered == msg.sender, "Invalid signature");

        _grantRole(INDEXER_ROLE, delegatee);
        emit RoleDelegated(msg.sender, delegatee, INDEXER_ROLE);
    }

    /// @notice Batch update connection priorities - restricted to pool managers
    function batchUpdatePriority(
        uint256 poolId,
        uint256[] calldata connIds,
        uint8[] calldata priorities
    ) external {
        require(connIds.length == priorities.length, "Length mismatch");
        Pool storage pool = pools[poolId];
        require(pool.manager == msg.sender || hasRole(DEFAULT_ADMIN_ROLE, msg.sender), "Not manager");

        for (uint256 i = 0; i < connIds.length; i++) {
            pool.connections[connIds[i]].priority = priorities[i];
        }
    }

    /// @notice Emergency pool migration - transfers management with role inheritance
    function migratePool(uint256 poolId, address newManager) external {
        Pool storage pool = pools[poolId];
        require(pool.manager == msg.sender, "Not current manager");
        require(newManager != address(0), "Invalid manager");

        pool.manager = newManager;

        // Transfer pool management capabilities to new manager
        // The role check uses getRoleAdmin to verify the caller can grant
        bytes32 adminRole = getRoleAdmin(POOL_MANAGER_ROLE);
        if (hasRole(adminRole, msg.sender) || hasRole(DEFAULT_ADMIN_ROLE, msg.sender)) {
            _grantRole(POOL_MANAGER_ROLE, newManager);
        }
    }

    /// @notice Reclaim expired connections and emit maintenance metrics
    function reclaimExpiredConnections(
        uint256 poolId,
        uint256[] calldata connIds,
        bool requestElevation
    ) external nonReentrant {
        Pool storage pool = pools[poolId];
        require(hasRole(INDEXER_ROLE, msg.sender) || hasRole(POOL_MANAGER_ROLE, msg.sender), "Unauthorized");

        uint256 reclaimed = 0;
        for (uint256 i = 0; i < connIds.length; i++) {
            Connection storage conn = pool.connections[connIds[i]];
            if (conn.active && (block.timestamp - conn.lastUsed) > 1 hours) {
                conn.active = false;
                pool.activeConnections--;
                reclaimed++;
            }
        }

        // Elevation requests are logged but require admin approval through governance
        // No automatic privilege escalation - must go through proper role admin
        if (requestElevation && reclaimed > 0) {
            emit MaintenanceCompleted(msg.sender, poolId, reclaimed);
        }
    }

    event MaintenanceCompleted(address indexed maintainer, uint256 indexed poolId, uint256 reclaimed);

    function getConnection(uint256 poolId, uint256 connId) external view returns (
        address owner, uint64 createdAt, uint64 lastUsed, bool active, uint8 priority
    ) {
        Connection storage conn = pools[poolId].connections[connId];
        return (conn.owner, conn.createdAt, conn.lastUsed, conn.active, conn.priority);
    }

    function getUserConnections(address user, uint256 poolId) external view returns (uint256[] memory) {
        return userConnections[user][poolId];
    }
}
